NEW_FILES = {FEED: '# backend/app/marketdata/shared_tick_feed.py\n#\n# ── STRATEGY_INDEPENDENCE_20261015 ── a tick socket for BB_V1 / BB_V2 / HA_V1\n# that does not need SCALP_V1.\n#\n# BUG: BB_V1, BB_V2 and HA_V1 have no socket of their own. They receive every\n# tick through get_ws_engines()[0] — the ZerodhaTickEngine that ONLY SCALP_V1\'s\n# selection_loop creates (it fans each tick out to BB_ENGINE_REGISTRY /\n# HA_ENGINE_REGISTRY). A licence with BB or HA but without SCALP_V1 never got\n# a socket: those strategies silently never traded.\n#\n# FIX: when (and only when) a BB/HA strategy is licensed+enabled and SCALP_V1\n# is NOT, this feed provides exactly the plumbing they use from the shared\n# engine — and nothing of SCALP_V1\'s (no candles, indicators, signals, paper\n# exits, MTM guard, timeline writes):\n#   * registers itself in ws_registry → engines[0] for BB / HA\n#   * same universe as SCALP_V1\'s engine: NIFTY weekly ±800 + BANKNIFTY\n#     current-month FUT + NIFTY / BANKNIFTY / SENSEX index tokens, MODE_FULL\n#   * .builders / .strategies[token].symbol (HA\'s universe discovery),\n#     .subscribe_additional_tokens (BB FUT/options, HA selections)\n#   * every tick → BB / HA on_tick(token, ltp, ts); index ticks →\n#     MarketIndicesState; universe CE/PE → LTPStore (as the shared engine)\n#   * on_connect → BB / HA on_ws_reconnect(); zombie-socket watchdog\n# Where SCALP_V1 runs (every machine today that runs BB/HA) this module does\n# nothing: the launcher logs "not needed" and returns. One socket either way.\n\nfrom __future__ import annotations\n\nimport asyncio\nimport threading\nimport time\nfrom typing import Dict, List, Optional, Tuple\n\nfrom app.event_bus.audit_logger import write_audit_log\n\nFENCE = "STRATEGY_INDEPENDENCE_20261015"\nFEED_CLIENTS = ("BB_V1", "BB_V2", "HA_V1")\nATM_RANGE = 800            # = selection_engine.ATM_RANGE (the shared universe)\nSTRIKE_STEP = 50\nRETRY_S = 120\nINDEX_ALLOWLIST = {"NIFTY 50": "NIFTY", "NIFTY BANK": "BANKNIFTY", "SENSEX": "SENSEX"}\n\n\nclass _Sym:\n    __slots__ = ("symbol",)\n\n    def __init__(self, symbol: str):\n        self.symbol = symbol\n\n\ndef _bb_registry():\n    try:\n        from app.core.engine_registry import BB_ENGINE_REGISTRY\n        return BB_ENGINE_REGISTRY\n    except Exception:\n        return []\n\n\ndef _ha_registry():\n    try:\n        from app.core.ha_engine_registry import HA_ENGINE_REGISTRY\n        return HA_ENGINE_REGISTRY\n    except Exception:\n        return []\n\n\ndef _market_open() -> bool:\n    from app.utils.market_hours import is_market_open\n    return is_market_open()\n\n\nclass SharedTickFeed:\n    """Feed-only stand-in for ZerodhaTickEngine\'s shared role (see header)."""\n\n    def __init__(self, kite_data, instrument_tokens: List[int], instruments_df=None,\n                 ticker_factory=None, register: bool = True):\n        self.strategy_id = "SHARED_FEED"\n        self.kite_data = kite_data\n        if instruments_df is None:\n            from app.fetcher.zerodha_instruments import load_instruments_df\n            instruments_df = load_instruments_df()\n        self.instruments_df = instruments_df\n        self._lock = threading.Lock()\n        self._started = False\n        self._connected = False\n        self._extra_tokens: set = set()\n        self._last_tick_ts = 0.0\n        self._last_connect_ts = 0.0\n        self._last_wd_action_ts = 0.0\n        self._wd_strikes = 0\n        self.ticks = 0\n\n        self.index_tokens: Dict[int, str] = {}\n        try:\n            rows = instruments_df[instruments_df["segment"].isin(["INDICES", "BSE-INDICES"])]\n            for _, r in rows.iterrows():\n                ts = str(r["tradingsymbol"]).upper()\n                if ts in INDEX_ALLOWLIST:\n                    self.index_tokens[int(r["instrument_token"])] = INDEX_ALLOWLIST[ts]\n        except Exception as e:\n            write_audit_log(f"[SHARED_FEED] index token resolve failed: {e!r}")\n\n        self.builders: Dict[int, None] = {}\n        self.strategies: Dict[int, _Sym] = {}\n        try:\n            sym_of = dict(zip(instruments_df["instrument_token"].astype(int),\n                              instruments_df["tradingsymbol"].astype(str)))\n        except Exception:\n            sym_of = {}\n        for tok in instrument_tokens:\n            tok = int(tok)\n            sym = sym_of.get(tok)\n            if not sym:\n                continue\n            self.builders[tok] = None\n            self.strategies[tok] = _Sym(sym)\n\n        if ticker_factory is None:\n            from app.marketdata.rotating_ticker import RotatingKiteTicker\n            ticker_factory = lambda: RotatingKiteTicker(       # noqa: E731\n                api_key=kite_data.api_key, access_token=kite_data.access_token, kind="data")\n        self.kws = ticker_factory()\n        self.kws.on_ticks = self._on_ticks\n        self.kws.on_connect = self._on_connect\n        self.kws.on_close = self._on_close\n        self.kws.on_error = self._on_error\n\n        if register:\n            from app.marketdata.ws_registry import register_ws_engine\n            register_ws_engine(self)\n        write_audit_log(f"[SHARED_FEED] built: {len(self.builders)} contracts + "\n                        f"{len(self.index_tokens)} indices (no SCALP_V1 on this machine)")\n\n    # ── the API BB / HA call on engines[0] ──\n    def subscribe_additional_tokens(self, tokens: List[int]):\n        if not tokens:\n            return\n        for t in tokens:\n            self._extra_tokens.add(int(t))\n\n        def _do():\n            try:\n                time.sleep(0.3)\n                if not self._connected:\n                    return              # _on_connect subscribes _extra_tokens\n                self.kws.subscribe(list(tokens))\n                self.kws.set_mode(self.kws.MODE_FULL, list(tokens))\n                write_audit_log(f"[SHARED_FEED] additional tokens subscribed: {len(tokens)}")\n            except Exception as e:\n                write_audit_log(f"[SHARED_FEED][ERROR] subscribe_additional_tokens: {e}")\n\n        threading.Thread(target=_do, daemon=True).start()\n\n    def start(self):\n        with self._lock:\n            if self._started:\n                return\n            self._started = True\n        threading.Thread(target=self._wait_and_connect, daemon=True, name="shared-feed-connect").start()\n        threading.Thread(target=self._tick_watchdog, daemon=True, name="shared-feed-watchdog").start()\n\n    def _wait_and_connect(self):\n        while not _market_open():\n            time.sleep(30)\n        try:\n            self.kws.connect(threaded=True)\n        except Exception as e:\n            write_audit_log(f"[SHARED_FEED][FATAL] connect: {e!r}")\n\n    # ── callbacks ──\n    def _on_connect(self, ws, response):\n        base = list(self.builders) + list(self.index_tokens)\n        toks = base + [t for t in self._extra_tokens if t not in base]\n        ws.subscribe(toks)\n        ws.set_mode(ws.MODE_FULL, toks)\n        write_audit_log(f"[SHARED_FEED] connected — {len(toks)} tokens "\n                        f"({len(base)} initial + {len(toks) - len(base)} extra)")\n        with self._lock:\n            self._connected = True\n            self._last_connect_ts = time.time()\n        for reg, tag in ((_bb_registry(), "BB"), (_ha_registry(), "HA")):\n            try:\n                for e in reg:\n                    e.on_ws_reconnect()\n            except Exception as ex:\n                write_audit_log(f"[SHARED_FEED][{tag}_RECONNECT_NOTIFY_ERROR] {ex}")\n\n    def _on_close(self, ws, code, reason):\n        write_audit_log(f"[SHARED_FEED] closed {code} {reason}")\n        with self._lock:\n            self._connected = False\n\n    def _on_error(self, ws, code, reason):\n        write_audit_log(f"[SHARED_FEED] error {code} {reason}")\n\n    def _on_ticks(self, ws, ticks):\n        self._last_tick_ts = time.time()\n        bb, ha = _bb_registry(), _ha_registry()\n        for tick in ticks:\n            token = tick.get("instrument_token")\n            ltp = tick.get("last_price")\n            if token is None or ltp is None:\n                continue\n            self.ticks += 1\n            ts = int(time.time())\n            try:\n                for e in bb:\n                    e.on_tick(token, ltp, ts)\n            except Exception as ex:\n                write_audit_log(f"[SHARED_FEED][BB_DISPATCH_ERROR] {ex}")\n            try:\n                for e in ha:\n                    e.on_tick(token, ltp, ts)\n            except Exception as ex:\n                write_audit_log(f"[SHARED_FEED][HA_DISPATCH_ERROR] {ex}")\n            name = self.index_tokens.get(token)\n            if name:\n                try:\n                    from app.marketdata.market_indices_state import MarketIndicesState\n                    MarketIndicesState.update_ltp(name, ltp)\n                except Exception:\n                    pass\n                continue\n            s = self.strategies.get(token)\n            if s and (s.symbol.endswith("CE") or s.symbol.endswith("PE")):\n                try:\n                    from app.marketdata.ltp_store import LTPStore\n                    LTPStore.update(s.symbol, ltp)\n                except Exception:\n                    pass\n\n    def _tick_watchdog(self):\n        """Zombie-socket guard — same rule as ZerodhaTickEngine (2026-06-11):\n        connected + market open + zero ticks for 120s → drop the protocol so\n        KiteTicker\'s auto-reconnect heals it."""\n        SILENT_S, POLL_S, COOLDOWN_S, BACKOFF_S = 120, 30, 90, 1800\n        while True:\n            try:\n                time.sleep(POLL_S)\n                if not self._connected or not _market_open():\n                    continue\n                base = max(self._last_tick_ts, self._last_connect_ts)\n                if base <= 0:\n                    continue\n                silent = time.time() - base\n                if silent < SILENT_S or time.time() - self._last_wd_action_ts < COOLDOWN_S:\n                    continue\n                if self._last_tick_ts > self._last_wd_action_ts:\n                    self._wd_strikes = 0\n                if self._wd_strikes >= 3 and silent < BACKOFF_S:\n                    continue\n                write_audit_log(f"[SHARED_FEED][WATCHDOG] connected but ZERO ticks for "\n                                f"{int(silent)}s during market hours — forcing reconnect")\n                self._wd_strikes += 1\n                self._last_wd_action_ts = time.time()\n                ws = getattr(self.kws, "ws", None)\n                if ws is not None:\n                    ws.sendClose(1000, "tick-watchdog")\n            except Exception as e:\n                try:\n                    write_audit_log(f"[SHARED_FEED][WATCHDOG] loop error: {e!r}")\n                except Exception:\n                    pass\n\n\n# ── launcher ─────────────────────────────────────────────────────────────\ndef needs_shared_feed(allows=None, registry=None) -> Tuple[bool, str]:\n    """(needed, reason). Needed iff a BB/HA strategy will run and SCALP_V1\n    (the only creator of the shared engine) will not."""\n    if registry is None:\n        from app.strategy.strategy_registry import STRATEGIES as registry\n    if allows is None:\n        from app.license import license_state\n        allows = license_state.license_allows_strategy\n\n    def runs(sid):\n        try:\n            return bool((registry.get(sid) or {}).get("enabled")) and bool(allows(sid))\n        except Exception:\n            return False\n\n    clients = [s for s in FEED_CLIENTS if runs(s)]\n    if not clients:\n        return False, "no BB/HA strategy on this licence"\n    if runs("SCALP_V1"):\n        return False, f"SCALP_V1 runs here and owns the shared socket ({\', \'.join(clients)} ride it)"\n    return True, f"{\', \'.join(clients)} licensed without SCALP_V1"\n\n\ndef _build_tokens(kite_trade) -> List[int]:\n    from app.fetcher.zerodha_instruments import load_nifty_weekly_universe\n    universe = load_nifty_weekly_universe(api_key=kite_trade.api_key,\n                                          access_token=kite_trade.access_token,\n                                          atm_range=ATM_RANGE, strike_step=STRIKE_STEP)\n    tokens = [int(o["instrument_token"]) for o in (universe or [])]\n    if not tokens:\n        return []\n    try:\n        from app.engine.bb_options.futures_resolver import resolve_current_month_banknifty_fut\n        r = resolve_current_month_banknifty_fut()\n        if r and int(r[0]) not in tokens:\n            tokens.append(int(r[0]))\n    except Exception as e:\n        write_audit_log(f"[SHARED_FEED][BB_FUT_INJECT_ERROR] {e}")\n    return tokens\n\n\nasync def shared_tick_feed_loop(zerodha_manager, *, _need=None, _build=None, _feed_cls=None,\n                                _engines=None, _sleep=asyncio.sleep, _max_cycles=None):\n    """Launched once at boot. Returns immediately when not needed; otherwise\n    waits for the broker, builds the universe, starts the feed and returns."""\n    await asyncio.sleep(0)\n    need, why = (_need or needs_shared_feed)()\n    write_audit_log(f"[SHARED_FEED] {\'starting\' if need else \'not needed\'} — {why}")\n    if not need:\n        return None\n    build = _build or _build_tokens\n    feed_cls = _feed_cls or SharedTickFeed\n    if _engines is None:\n        from app.marketdata.ws_registry import get_ws_engines as _engines\n    n = 0\n    while _max_cycles is None or n < _max_cycles:\n        n += 1\n        try:\n            if _engines():\n                write_audit_log("[SHARED_FEED] a shared engine is already registered — standing down")\n                return None\n            if not zerodha_manager.is_ready():\n                await _sleep(30)\n                continue\n            kt, kd = zerodha_manager.get_trade_kite(), zerodha_manager.get_data_kite()\n            if not kt or not kd:\n                await _sleep(30)\n                continue\n            tokens = await asyncio.to_thread(build, kt)\n            if not tokens:\n                write_audit_log(f"[SHARED_FEED] weekly universe empty — retry in {RETRY_S}s")\n                await _sleep(RETRY_S)\n                continue\n            feed = await asyncio.to_thread(feed_cls, kd, tokens)\n            feed.start()\n            write_audit_log(f"[SHARED_FEED] started for {why}")\n            return feed\n        except Exception as e:\n            write_audit_log(f"[SHARED_FEED][ERROR] {e!r} — retry in {RETRY_S}s")\n            await _sleep(RETRY_S)\n    return None\n',
             T: '# backend/app/marketdata/test_strategy_independence.py — fence STRATEGY_INDEPENDENCE_20261015\n#\n#   A. SharedTickFeed — BB_V1 / BB_V2 / HA_V1 without SCALP_V1\n#      need matrix · registry (engines[0]) · the attributes BB/HA use ·\n#      fan-out of every tick (incl. extra tokens) · index → MarketIndicesState\n#      · CE/PE → LTPStore · one failing consumer never starves the others ·\n#      on_connect subscribes initial+index+extra and notifies reconnect ·\n#      HA\'s own _symbol_for_token resolves through the feed · launcher paths\n#   B. NIFTY50 alias in MarketDataContext (static)\n#   C. TMA / TMA2 carried legs outside today\'s band: subscribed, candles +\n#      LTPStore, NOT selection candidates · expiry_hint · loop wiring ·\n#      accurate empty-universe alerts (TMA, TMA2, VET)\n#\n# Run: cd backend && python3 app/marketdata/test_strategy_independence.py\n\nfrom __future__ import annotations\n\nimport asyncio\nimport os\nimport sys\nimport tempfile\nimport time\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve()\nBACKEND = Path(HERE.parents[2])\nREPO = BACKEND.parent\nif str(BACKEND) not in sys.path:\n    sys.path.insert(0, str(BACKEND))\nos.environ.setdefault("SCALP_APP_HOME", tempfile.mkdtemp())\n\nimport pandas as pd  # noqa: E402\n\nFENCE = "STRATEGY_INDEPENDENCE_20261015"\nFAILS: list = []\nOK = [0]\n\n\ndef check(name, ok, note=""):\n    print(f"  {\'PASS\' if ok else \'FAIL\'}  {name}{(\'  — \' + str(note)) if (note and not ok) else \'\'}")\n    if ok:\n        OK[0] += 1\n    else:\n        FAILS.append(name)\n\n\nimport app.marketdata.shared_tick_feed as SF  # noqa: E402\nfrom app.marketdata.ltp_store import LTPStore  # noqa: E402\nfrom app.marketdata.market_indices_state import MarketIndicesState as MIS  # noqa: E402\nfrom app.marketdata import ws_registry  # noqa: E402\nfrom app.core.engine_registry import BB_ENGINE_REGISTRY  # noqa: E402\nfrom app.core.ha_engine_registry import HA_ENGINE_REGISTRY  # noqa: E402\n\nDF = pd.DataFrame([\n    {"instrument_token": 256265, "tradingsymbol": "NIFTY 50", "segment": "INDICES", "name": "NIFTY 50",\n     "expiry": None, "strike": 0, "instrument_type": "EQ"},\n    {"instrument_token": 260105, "tradingsymbol": "NIFTY BANK", "segment": "INDICES", "name": "NIFTY BANK",\n     "expiry": None, "strike": 0, "instrument_type": "EQ"},\n    {"instrument_token": 265, "tradingsymbol": "SENSEX", "segment": "BSE-INDICES", "name": "SENSEX",\n     "expiry": None, "strike": 0, "instrument_type": "EQ"},\n    {"instrument_token": 11, "tradingsymbol": "NIFTY26O1922600CE", "segment": "NFO-OPT", "name": "NIFTY",\n     "expiry": "2026-10-19", "strike": 22600, "instrument_type": "CE"},\n    {"instrument_token": 12, "tradingsymbol": "NIFTY26O1922600PE", "segment": "NFO-OPT", "name": "NIFTY",\n     "expiry": "2026-10-19", "strike": 22600, "instrument_type": "PE"},\n    {"instrument_token": 13, "tradingsymbol": "NIFTY26O1924500CE", "segment": "NFO-OPT", "name": "NIFTY",\n     "expiry": "2026-10-19", "strike": 24500, "instrument_type": "CE"},\n    {"instrument_token": 14, "tradingsymbol": "NIFTY26O2722600CE", "segment": "NFO-OPT", "name": "NIFTY",\n     "expiry": "2026-10-27", "strike": 22600, "instrument_type": "CE"},\n    {"instrument_token": 99, "tradingsymbol": "BANKNIFTY26OCTFUT", "segment": "NFO-FUT", "name": "BANKNIFTY",\n     "expiry": "2026-10-27", "strike": 0, "instrument_type": "FUT"},\n])\n\n\nclass Ticker:\n    MODE_FULL = "full"\n\n    def __init__(self):\n        self.subs, self.modes, self.connected = [], [], 0\n\n    def subscribe(self, toks):\n        self.subs.append(list(toks))\n\n    def set_mode(self, mode, toks):\n        self.modes.append((mode, list(toks)))\n\n    def connect(self, threaded=True):\n        self.connected += 1\n\n\nclass Consumer:\n    def __init__(self, boom=False):\n        self.ticks, self.reconnects, self.boom = [], 0, boom\n\n    def on_tick(self, token, ltp, ts):\n        if self.boom:\n            raise RuntimeError("consumer down")\n        self.ticks.append((token, ltp))\n\n    def on_ws_reconnect(self):\n        self.reconnects += 1\n\n\ndef clean():\n    ws_registry._WS_ENGINE_REGISTRY.clear()\n    BB_ENGINE_REGISTRY.clear()\n    HA_ENGINE_REGISTRY.clear()\n    with LTPStore._lock:\n        for s in DF["tradingsymbol"]:\n            LTPStore._prices.pop(s, None)\n            LTPStore._timestamps.pop(s, None)\n    with MIS._lock:\n        MIS._ltp.clear()\n        MIS._ltp_ws_ts.clear()\n\n\ndef feed(tokens=(11, 12, 99)):\n    t = Ticker()\n    f = SF.SharedTickFeed(None, list(tokens), instruments_df=DF, ticker_factory=lambda: t)\n    return f, t\n\n\n# ═════════════════════════════════════════════════════════════════════\ndef t_need():\n    print("── A1. when is the shared feed needed ──")\n    reg = {s: {"enabled": True} for s in ("SCALP_V1", "BB_V1", "BB_V2", "HA_V1")}\n    case = lambda lic, r=reg: SF.needs_shared_feed(allows=lambda s: s in lic, registry=r)[0]   # noqa: E731\n    check("HA_V1 without SCALP_V1 → needed", case({"HA_V1"}))\n    check("BB_V1 + BB_V2 without SCALP_V1 → needed", case({"BB_V1", "BB_V2"}))\n    check("HA_V1 + SCALP_V1 → NOT needed (SCALP_V1 owns the socket — your machine)", not case({"HA_V1", "SCALP_V1"}))\n    check("IC / TSG / TMA / VET only (your friend) → NOT needed", not case({"IC_V2", "TSG_V1", "TMA_V2", "VET_V1"}))\n    check("SCALP_V1 only → NOT needed", not case({"SCALP_V1"}))\n    r2 = dict(reg, SCALP_V1={"enabled": False})\n    check("SCALP_V1 licensed but disabled in the registry + HA → needed", case({"HA_V1", "SCALP_V1"}, r2))\n    r3 = dict(reg, HA_V1={"enabled": False})\n    check("HA licensed but disabled, no SCALP_V1 → NOT needed", not case({"HA_V1"}, r3))\n    check("licence check raising → treated as not licensed (no feed, no crash)",\n          SF.needs_shared_feed(allows=lambda s: 1 / 0, registry=reg)[0] is False)\n\n\ndef t_feed():\n    print("── A2. SharedTickFeed ──")\n    clean()\n    f, t = feed()\n    check("registers itself → get_ws_engines()[0] (what BB / HA read)", ws_registry.get_ws_engines()[0] is f)\n    check("index tokens resolved (NIFTY / BANKNIFTY / SENSEX)",\n          f.index_tokens == {256265: "NIFTY", 260105: "BANKNIFTY", 265: "SENSEX"}, f.index_tokens)\n    check(".builders = the universe tokens", sorted(f.builders) == [11, 12, 99])\n    check(".strategies[token].symbol (HA\'s resolver)", f.strategies[11].symbol == "NIFTY26O1922600CE")\n    try:\n        from app.engine.ha_options.ha_tick_engine import _symbol_for_token\n        check("HA\'s own _symbol_for_token resolves through the feed",\n              _symbol_for_token(12, f) == "NIFTY26O1922600PE")\n    except ImportError as e:\n        print(f"  ! ha_tick_engine not importable here ({e}) — skipped")\n    check("no SCALP_V1 machinery on the feed (no indicators / signal_router / paper exits)",\n          not any(hasattr(f, a) for a in ("indicators", "signal_router", "condition_engine", "_maybe_mtm_squareoff")))\n\n    # subscribe before connect → carried into on_connect\n    f.subscribe_additional_tokens([14, 13])\n    time.sleep(0.5)\n    check("subscribe before connect: queued, not sent", t.subs == [] and {13, 14} <= f._extra_tokens)\n    bb1, bb2, ha = Consumer(), Consumer(), Consumer()\n    BB_ENGINE_REGISTRY.extend([bb1, bb2])\n    HA_ENGINE_REGISTRY.append(ha)\n    f._on_connect(t, {})\n    sent = set(t.subs[-1])\n    check("on_connect subscribes universe + indices + queued extras",\n          sent == {11, 12, 99, 256265, 260105, 265, 13, 14}, sorted(sent))\n    check("…in MODE_FULL (as the shared engine)", t.modes[-1][0] == "full" and set(t.modes[-1][1]) == sent)\n    check("…and notifies BB + HA on_ws_reconnect", bb1.reconnects == bb2.reconnects == ha.reconnects == 1)\n    # subscribe after connect → sent live\n    f.subscribe_additional_tokens([77])\n    time.sleep(0.6)\n    check("subscribe after connect: sent immediately", [77] in t.subs)\n\n    ticks = [{"instrument_token": 99, "last_price": 55100.0},       # BB FUT\n             {"instrument_token": 11, "last_price": 120.5},\n             {"instrument_token": 256265, "last_price": 22680.0},   # index\n             {"instrument_token": 14, "last_price": 150.0},         # extra token\n             {"instrument_token": None, "last_price": 1.0},\n             {"instrument_token": 12, "last_price": None}]\n    f._on_ticks(t, ticks)\n    want = [(99, 55100.0), (11, 120.5), (256265, 22680.0), (14, 150.0)]\n    check("every valid tick fans out to BOTH BB engines", bb1.ticks == want and bb2.ticks == want, bb1.ticks)\n    check("…and to HA (index + extra tokens included, as the shared engine)", ha.ticks == want, ha.ticks)\n    check("index tick → MarketIndicesState (WS-fresh → index REST feeder stays idle)",\n          MIS._ltp.get("NIFTY") == 22680.0 and not MIS.ws_stale(("NIFTY",), 5.0))\n    check("universe CE → LTPStore", LTPStore.get("NIFTY26O1922600CE") == 120.5)\n    check("FUT not written to LTPStore (shared engine: CE/PE only; BB publishes its own)",\n          LTPStore.get("BANKNIFTY26OCTFUT") is None)\n    # one consumer failing\n    clean()\n    f, t = feed()\n    bad, good, ha = Consumer(boom=True), Consumer(), Consumer()\n    BB_ENGINE_REGISTRY.extend([bad, good])\n    HA_ENGINE_REGISTRY.append(ha)\n    f._on_ticks(t, [{"instrument_token": 11, "last_price": 121.0}])\n    check("a raising BB engine never starves HA or LTPStore",\n          ha.ticks == [(11, 121.0)] and LTPStore.get("NIFTY26O1922600CE") == 121.0)\n    check("start() connects once, only when the market is open (threaded wait)",\n          hasattr(f, "_wait_and_connect") and hasattr(f, "_tick_watchdog"))\n    clean()\n\n\ndef t_launcher():\n    print("── A3. launcher ──")\n\n    class Mgr:\n        def __init__(self, ready=True):\n            self.ready = ready\n        def is_ready(self):\n            return self.ready\n        def get_trade_kite(self):\n            return object()\n        def get_data_kite(self):\n            return object()\n\n    slept = []\n\n    async def sl(s):\n        slept.append(s)\n\n    built = []\n\n    class FakeFeed:\n        def __init__(self, kd, toks):\n            built.append(toks)\n            self.started = False\n        def start(self):\n            self.started = True\n\n    r = asyncio.run(SF.shared_tick_feed_loop(Mgr(), _need=lambda: (False, "x"), _feed_cls=FakeFeed,\n                                             _engines=lambda: [], _sleep=sl, _max_cycles=3))\n    check("not needed → returns at once, builds nothing", r is None and not built and not slept)\n    r = asyncio.run(SF.shared_tick_feed_loop(Mgr(), _need=lambda: (True, "HA"), _build=lambda k: [11, 12],\n                                             _feed_cls=FakeFeed, _engines=lambda: [], _sleep=sl, _max_cycles=3))\n    check("needed → builds once with the universe, starts, returns the feed",\n          isinstance(r, FakeFeed) and r.started and built == [[11, 12]], built)\n    built.clear(); slept.clear()\n    r = asyncio.run(SF.shared_tick_feed_loop(Mgr(ready=False), _need=lambda: (True, "HA"), _build=lambda k: [11],\n                                             _feed_cls=FakeFeed, _engines=lambda: [], _sleep=sl, _max_cycles=3))\n    check("broker not ready → waits (30s steps), builds nothing", r is None and not built and slept == [30, 30, 30])\n    slept.clear()\n    r = asyncio.run(SF.shared_tick_feed_loop(Mgr(), _need=lambda: (True, "HA"), _build=lambda k: [],\n                                             _feed_cls=FakeFeed, _engines=lambda: [], _sleep=sl, _max_cycles=2))\n    check("empty universe → retry every 120s", r is None and slept == [SF.RETRY_S, SF.RETRY_S])\n    slept.clear()\n    r = asyncio.run(SF.shared_tick_feed_loop(Mgr(), _need=lambda: (True, "HA"), _build=lambda k: 1 / 0,\n                                             _feed_cls=FakeFeed, _engines=lambda: [], _sleep=sl, _max_cycles=2))\n    check("build raising → logged, retried, loop alive", r is None and slept == [SF.RETRY_S, SF.RETRY_S])\n    built.clear()\n    r = asyncio.run(SF.shared_tick_feed_loop(Mgr(), _need=lambda: (True, "HA"), _build=lambda k: [11],\n                                             _feed_cls=FakeFeed, _engines=lambda: ["zte"], _sleep=sl, _max_cycles=2))\n    check("an engine already registered → stands down (never a second socket)", r is None and not built)\n\n\n# ═════════════════════════════════════════════════════════════════════\ndef t_frontend():\n    print("── B. NIFTY50 alias (static) ──")\n    p = REPO / "frontend/src/context/MarketDataContext.jsx"\n    if not p.exists():\n        print("  ! frontend tree not found — skipped")\n        return\n    s = p.read_text(encoding="utf-8")\n    blk = s[s.find("const mergedLtpMap"):s.find("// ── SPOT_IN_LTPMAP END ──")]\n    check("mergedLtpMap aliases NIFTY50 from indices.NIFTY", FENCE in blk and "m.NIFTY50" in blk)\n    check("…only when nothing publishes NIFTY50 (ORB\'s own print wins)", "m.NIFTY50 == null" in blk)\n\n\n# ═════════════════════════════════════════════════════════════════════\ndef t_carry(modname, cls, label):\n    print(f"── C. {label}: carried legs ──")\n    import importlib\n    M = importlib.import_module(modname)\n    clean()\n    e = getattr(M, cls)(None, DF, lambda *a: None, capture_dir=None)\n    e._spot_token = 256265\n    e._builders = {256265: M.CandleBuilder(), 11: M.CandleBuilder()}\n    e._tok2sym = {11: "NIFTY26O1922600CE"}\n    e.chain.put_meta("NIFTY26O1922600CE", 22600, "2026-10-19", "CE", 11)\n    added = e.ensure_symbols(["NIFTY26O1924500CE", "NIFTY26O1922600CE", None, "NOPE"])\n    check(f"{label}: out-of-band carried leg subscribed (builder + token map)",\n          added == ["NIFTY26O1924500CE"] and 13 in e._builders and e._tok2sym.get(13) == "NIFTY26O1924500CE", added)\n    check(f"{label}: in-band / None / unknown symbols skipped", 11 in e._builders and len(e._builders) == 3)\n    check(f"{label}: NOT a selection candidate (no chain meta → backtest band parity)",\n          e.chain.symbols("CE") == ["NIFTY26O1922600CE"])\n    check(f"{label}: idempotent", e.ensure_symbols(["NIFTY26O1924500CE"]) == [])\n    base = (int(time.time()) // 60) * 60 - 600\n\n    class TS:\n        def __init__(self, v): self.v = v\n        def timestamp(self): return self.v\n    e._on_ticks(None, [{"instrument_token": 13, "last_price": 3.1, "exchange_timestamp": TS(base + 5)},\n                       {"instrument_token": 13, "last_price": 3.4, "exchange_timestamp": TS(base + 65)}])\n    c = e.chain._c.get("NIFTY26O1924500CE", {}).get(base)\n    check(f"{label}: carried leg builds candles (manager prices exits off them)", c is not None and c["close"] == 3.1, c)\n    check(f"{label}: carried leg published to LTPStore (TMA_TICK_LTP_PUBLISH)", LTPStore.get("NIFTY26O1924500CE") == 3.4)\n    import datetime as _d\n    h = e.expiry_hint("2026-10-20", today=_d.date(2026, 10, 15))\n    check(f"{label}: expiry_hint names computed vs listed expiries",\n          "2026-10-20" in h and "2026-10-19" in h and "2026-10-27" in h, h)\n    clean()\n\n\ndef t_wiring():\n    print("── C/A. wiring (static) ──")\n    for rel, tag in (("app/engine/tma2/tma2_selection_loop.py", "TMA2"), ("app/engine/tma/tma_selection_loop.py", "TMA")):\n        s = (BACKEND / rel).read_text(encoding="utf-8")\n        i_e = s.find("engine.ensure_symbols(")\n        i_s = s.find("    engine.start()")\n        check(f"{tag} loop: carried legs subscribed BEFORE engine.start()", 0 < i_e < i_s, (i_e, i_s))\n        check(f"{tag} loop: misleading \'only refreshes when MISSING\' alert gone",\n              "only refreshes when the file is MISSING" not in s and "engine.expiry_hint(expiry_iso)" in s)\n    s = (BACKEND / "app/engine/vet/vet_selection_loop.py").read_text(encoding="utf-8")\n    check("VET loop: empty-universe alert names the expiries", "tick.expiry_hint(expiry_iso)" in s)\n    s = (BACKEND / "app/api_server.py").read_text(encoding="utf-8")\n    i_f = s.find("INDEX_LTP_FEEDER_20261015 END (feeder launch)")\n    i_s = s.find(f"{FENCE} BEGIN (shared feed launch)")\n    blk = s[i_s:s.find(f"{FENCE} END (shared feed launch)")]\n    check("api_server: shared feed launched after the index feeder", 0 < i_f < i_s)\n    check("…own _boot_guard + _supervise, decision inside the loop",\n          \'_boot_guard("shared_tick_feed")\' in blk and "shared_tick_feed_loop(zerodha_manager)" in blk)\n\n\nif __name__ == "__main__":\n    t_need()\n    t_feed()\n    t_launcher()\n    t_frontend()\n    t_carry("app.engine.tma2.tma2_tick_engine", "TMA2TickEngine", "TMA2 engine (Timberwolf + Velvet)")\n    t_carry("app.engine.tma.tma_tick_engine", "TMATickEngine", "TMA_V1 engine")\n    t_wiring()\n    clean()\n    if FAILS:\n        print(f"\\n{len(FAILS)} FAILURES: {FAILS}")\n        sys.exit(1)\n    print(f"\\nALL {OK[0]} STRATEGY INDEPENDENCE CHECKS PASSED")\n'}


def die(m):
    print(f"\n✗ {m}"); sys.exit(1)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", default=os.environ.get("SCALP_REPO", "/Users/anbu/dev/scalp-app"))
    ap.add_argument("--allow-dirty", action="store_true")
    ap.add_argument("--skip-tests", action="store_true")
    ap.add_argument("--skip-esbuild", action="store_true")
    a = ap.parse_args()
    repo = Path(a.repo).expanduser().resolve()
    targets = sorted({f for f, *_ in EDITS})
    staged = {}
    for rel in targets:
        p = repo / rel
        if not p.exists():
            die(f"missing {rel}")
        txt = p.read_text(encoding="utf-8")
        if FENCE in txt:
            die(f"{rel} already carries {FENCE} — already applied, nothing to do")
        staged[rel] = txt
    for rel, fences in PREREQ.items():
        for f in fences:
            if f not in staged[rel]:
                die(f"prerequisite {f!r} not found in {rel}")
    for rel in NEW_FILES:
        if (repo / rel).exists():
            die(f"{rel} already exists — mixed state; remove it (or git checkout) and re-run")
    try:
        dirty = [r for r in targets if subprocess.run(["git", "status", "--porcelain", "--", r], cwd=repo,
                 capture_output=True, text=True, timeout=30).stdout.strip()]
    except Exception:
        dirty = []
    if dirty and not a.allow_dirty:
        die("uncommitted changes in " + ", ".join(dirty) + " — commit/stash first or --allow-dirty")
    original = dict(staged)
    for rel, old, new, c in EDITS:
        n = staged[rel].count(old)
        if n != c:
            die(f"anchor matched {n}× (need {c}) in {rel}:\n{old[:300]}")
        staged[rel] = staged[rel].replace(old, new)
    for rel in targets:
        if FENCE not in staged[rel]:
            die(f"internal: {rel} edited without the fence marker")
    with tempfile.TemporaryDirectory() as td:
        for rel, txt in [(r, staged[r]) for r in targets if r.endswith(".py")] + list(NEW_FILES.items()):
            tp = Path(td) / Path(rel).name
            tp.write_text(txt, encoding="utf-8")
            try:
                py_compile.compile(str(tp), doraise=True)
            except py_compile.PyCompileError as e:
                die(f"py_compile failed for {rel}: {e}")
        print(f"  ✓ py_compile (edited + {len(NEW_FILES)} new)")
        jsx = [r for r in targets if r.endswith((".js", ".jsx"))]
        if jsx and not a.skip_esbuild:
            esb = None
            for c in (repo / "frontend/node_modules/.bin/esbuild", repo / "desktop/node_modules/.bin/esbuild"):
                if c.exists():
                    esb = str(c); break
            esb = esb or shutil.which("esbuild")
            if not esb:
                die("esbuild not found (frontend/node_modules/.bin) — run npm install, or --skip-esbuild")
            for rel in jsx:
                tp = Path(td) / ("x_" + Path(rel).name)
                tp.write_text(staged[rel], encoding="utf-8")
                r = subprocess.run([esb, str(tp), "--loader:.js=jsx", "--loader:.jsx=jsx", "--log-level=error"],
                                   capture_output=True, text=True)
                if r.returncode != 0:
                    die(f"esbuild could not parse staged {rel}:\n{r.stderr[:2000]}")
            print(f"  ✓ esbuild parsed {len(jsx)} staged JSX file(s)")
    for rel in targets:
        p = repo / rel
        shutil.copy2(p, p.with_name(p.name + f".bak-{FENCE}"))
        p.write_text(staged[rel], encoding="utf-8")
        print(f"  ✓ wrote {rel}")
    for rel, txt in NEW_FILES.items():
        (repo / rel).write_text(txt, encoding="utf-8")
        print(f"  ✓ created {rel}")

    def rollback(why):
        for rel in targets:
            (repo / rel).write_text(original[rel], encoding="utf-8")
            (repo / rel).with_name(Path(rel).name + f".bak-{FENCE}").unlink(missing_ok=True)
        for rel in NEW_FILES:
            (repo / rel).unlink(missing_ok=True)
        die(why + " — every file restored")

    if not a.skip_tests:
        env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1",
                   SCALP_APP_HOME=tempfile.mkdtemp(prefix="scalp_test_home_"),
                   PYTHONPATH=str(repo / "backend") + os.pathsep + os.environ.get("PYTHONPATH", ""))
        r = subprocess.run([sys.executable, "-c",
                            "import app.marketdata.shared_tick_feed, app.engine.tma2.tma2_selection_loop, app.engine.tma.tma_selection_loop, app.engine.vet.vet_selection_loop; print('ok')"],
                           cwd=repo / "backend", capture_output=True, text=True, env=env, timeout=300)
        if r.returncode != 0:
            print(r.stderr[-3000:]); rollback("a touched module no longer imports")
        print("  ✓ shared_tick_feed + TMA / TMA2 / VET loops import")
        for suite in SUITES:
            if not (repo / "backend" / suite).exists():
                print(f"  ! {suite} not found — skipped")
                continue
            print(f"  … {Path(suite).name}")
            r = subprocess.run([sys.executable, suite], cwd=repo / "backend", capture_output=True, text=True,
                               env=env, timeout=600)
            last = (r.stdout.strip().splitlines() or ["(no output)"])[-1]
            if r.returncode != 0 or "  FAIL  " in r.stdout:
                print(r.stdout[-4000:]); print(r.stderr[-2000:]); rollback(f"suite {suite} FAILED")
            print(f"  ✓ {Path(suite).name}: {last}")
    for rel in targets + list(NEW_FILES):
        for sp, dp in MIRRORS.items():
            if rel.startswith(sp) and (repo / dp).exists():
                dst = repo / (dp + rel[len(sp):])
                dst.parent.mkdir(parents=True, exist_ok=True)
                if dst.exists():
                    shutil.copy2(dst, dst.with_name(dst.name + f".bak-{FENCE}"))
                shutil.copy2(repo / rel, dst)
                print(f"  ✓ mirrored → {dst.relative_to(repo)}")
    print(f"\n✓ {FENCE} applied. Rebuild (deploy-scalp.command). On launch the log says one of:\n"
          f"  • '[SHARED_FEED] not needed — SCALP_V1 runs here…'   (your machine — nothing changes)\n"
          f"  • '[SHARED_FEED] not needed — no BB/HA strategy…'     (your friend's licence)\n"
          f"  • '[SHARED_FEED] starting — HA_V1 licensed without SCALP_V1'  (a BB/HA-only licence)\n"
          f"  Velvet panel NIFTY spot now ticks everywhere; TMA carries log '[TICK][CARRY]' when used.")

if __name__ == "__main__":
    main()
